avaselenium-beginner/");\n\n        Locator module2Link = page.locator("//a[contains(text(),\'Module 2:\')]");\n        module2Link.scrollIntoViewIfNeeded();\n        page.waitForTimeout(1000);\n        module2Link.click();\n\n        Challenge01();\n        Challenge02(page);\n        Challenge03(page);\n\n        // Choosing to close all Browser after completion\n        System.out.println("Browser is running. Press ENTER in the console to close...");\n        System.in.read();  // <-- keeps your script alive until you press Enter\n\n        context.close();\n        browser.close();\n        playwright.close();\n\n    }\n    private static void printDialogMsg() {\n        page.onceDialog(dialog -> {\n            System.out.println("Dialog message: " + dialog.message());\n            dialog.accept();\n        });\n    }\n    private static void Challenge01() {\n        page.waitForTimeout(1000);\n        page.evaluate("window.scrollTo({top: 0, behavior: \'smooth\'})");\n\n        for(int i = 1; i<=4;i++) {\n            Challenge01a(page,i);\n        }\n    }\n    private static void Challenge01a(Page page, int idx) {\n        // 1. Select dropdown by index\n        page.locator("#challenge1-dropdown").selectOption(new SelectOption().setIndex(idx));\n\n        // 2. Click stack and channel\n        page.waitForTimeout(500);\n        page.click("#stack-java-playwright");\n        page.waitForTimeout(500);\n        page.click("#channel-playwright");\n\n        // 3. Click Generate Passcode\n        page.waitForTimeout(500);\n        page.click("#generate-passcode-btn");\n\n        // 4. Extract passcode (Playwright auto-waits until visible)\n        String fullText = page.locator("#generated-passcode-label").innerText();\n        String passcode = fullText.replaceAll("\\D+", "");\n\n        // 5. Enter passcode\n        page.waitForTimeout(500);\n        page.fill("#entered-passcode", passcode);\n\n        // 6. Click Validate\n        page.waitForTimeout(500);\n        printDialogMsg();\n        page.waitForTimeout(500);\n        page.click("#validate-challenge1-btn");\n\n    }\n\n    private static void Challenge02(Page page) throws IOException{\n        // 0. Scroll to top\n        page.evaluate("window.scrollTo(0, 0)");\n        page.waitForTimeout(1000);\n\n        // 1. Scroll to bottom of page\n        page.evaluate("window.scrollTo({ top: document.body.scrollHeight, behavior: \'smooth\' })");\n        page.waitForTimeout(800);\n\n        // 2. Get a FrameLocator for the iframe\n        FrameLocator practiceFrame = page.frameLocator("#practice-frame");\n\n        // 3. Get locator for the link inside the iframe\n        Locator generatorLink = practiceFrame.locator("#number-generator-link");\n\n        // 4. Click link inside iframe, opening the number generator in a new tab\n        Page generatorPage = page.waitForPopup(() -> {\n            generatorLink.scrollIntoViewIfNeeded();\n            generatorLink.click();\n        });\n\n        // 5. Click the Roll button on generator page\n        generatorPage.locator("#touchBtn").click();\n        generatorPage.waitForTimeout(1000);\n\n        // 6. Get the random number via JS\n        Object result = generatorPage.evaluate(\n                "() => {" +\n                        "const copyBtn = document.getElementById(\'copy_btn\');" +\n                        "if (!copyBtn) return \'\';" +\n                        "const sel = copyBtn.getAttribute(\'data-clipboard-target\');" +\n                        "if (!sel) return \'\';" +\n                        "const el = document.querySelector(sel);" +\n                        "if (!el) return \'\';" +\n                        "let txt = el.innerText || el.textContent || \'\';" +\n                        "return txt.trim();" +\n                        "}"\n        );\n\n\n        // Safely convert to String\n        String randomNumber = result == null ? "" : result.toString();\n        System.out.println("Generated number: " + randomNumber);\n\n        // 7. Screenshot generator page\n        String screenshotPath = takeScreenshot(generatorPage, "JavaPlaywrightScreenshot");\n\n        // 8. Close child tab\n        generatorPage.close();\n\n        // 9. Back on main page \u2013 fill code and upload screenshot\n        page.waitForTimeout(1000);  // small wait just for visual confirmation\n\n        page.locator("#frame-code-input").fill(randomNumber);\n\n        page.locator("#frame-screenshot-upload")\n                .setInputFiles(java.nio.file.Paths.get(screenshotPath));\n\n        // 10. Handle alert & validate Challenge 2\n        page.waitForTimeout(1000);\n        printDialogMsg();  // register alert handler BEFORE clicking\n        page.locator("#validate-challenge2-btn").click();\n\n    }\n    private static String takeScreenshot(Page childPage, String baseFileName) throws IOException{\n        String timestamp = java.time.LocalDateTime.now()\n                .format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd_HH-mm-ss"));\n        Path folder = Paths.get("D:\\Kevin\\Resume\\Jobs\\Cognizant\\Client\\VISA\\Image");\n\n        if (!Files.exists(folder)) {\n            Files.createDirectories(folder);\n        }\n        Path filePath = folder.resolve(baseFileName + "_" + timestamp + ".png");\n        childPage.screenshot(new Page.ScreenshotOptions().setPath(filePath).setFullPage(true));\n        return filePath.toString();\n    }\n    private static void Challenge03(Page page) {\n        // 0. Scroll to top\n        page.evaluate("window.scrollTo(0, 0)");\n        page.waitForTimeout(1000);\n\n        // 1. Find Hover Target Area, scroll there\n        Locator hoverTargetArea = page.locator(\n                "xpath=//div[contains(text(),\'Hint: Selenium Actions.moveToElement can trigger h\')]"\n        );\n        hoverTargetArea.scrollIntoViewIfNeeded();\n        page.waitForTimeout(1000);\n\n        // 2. Hover mouse over the target area\n        hoverTargetArea.hover();\n        page.waitForTimeout(1000);\n\n        // 3. Drag & Drop\n        Locator dragMe   = page.locator("#drag-source");\n        Locator dropHere = page.locator("#drop-target");\n\n        // Playwright has built-in drag-and-drop\n        dragMe.dragTo(dropHere);\n        page.waitForTimeout(1000);\n\n        // 4. Double-click the button\n        Locator doubleClickBtn = page.locator("#double-click-btn");\n        doubleClickBtn.dblclick();\n        page.waitForTimeout(1000);\n\n        // 5. Right-click the area\n        Locator rightClickArea = page.locator("#right-click-area");\n        rightClickArea.click(new Locator.ClickOptions().setButton(MouseButton.RIGHT));\n        page.waitForTimeout(1000);\n\n        // 6. Keyboard Input Challenge\n        Locator keyInputText = page.locator("#keyboard-input");\n        keyInputText.fill("selenium");\n        page.waitForTimeout(1000);\n\n        // 7. Click the button and handle alert\n        printDialogMsg();  // register dialog handler BEFORE clicking\n        page.locator("#validate-challenge3-btn").click();\n    }\n}\n'})]})})},At=()=>{const e=Dt();return(0,Rt.jsx)("div",{style:{minHeight:"100vh",padding:e?"20px 10px":"40px 20px",background:"linear-gradient(180deg, #0077b6 0%, #0096c7 40%, #48cae4 100%)",display:"flex",justifyContent:"center",alignItems:"flex-start"},children:(0,Rt.jsxs)("div",{style:{width:e?"100%":"90%",maxWidth:"1000px"},children:[(0,Rt.jsxs)("div",{style:{display:"flex",flexDirection:e?"column":"row",justifyContent:"space-between",alignItems:e?"flex-start":"center",marginBottom:"16px",color:"#ffffff"},children:[(0,Rt.jsx)("h1",{style:{margin:0,fontSize:e?"18px":"22px",fontWeight:700},children:"Module 3a \u2013 Elements | Typescript Playwright Automation Demo"}),(0,Rt.jsx)(vt,{to:"/",style:{marginTop:e?"8px":0,color:"#ffdd57",textDecoration:"underline",fontWeight:600,fontSize:e?"13px":"14px"},children:"\u2190 Back to Home"})]}),(0,Rt.jsx)("div",{style:{backgroundColor:"#0f0f0f",pa